namespace CombinedStudio;
internal sealed class CrosshairRandomOptions {
 public string Category {get;set;}="All designs";
 public int Duration {get;set;}=3;
 public int Delay {get;set;}=5;
 public bool LockColor {get;set;}
 public bool LockShape {get;set;}
 public bool Large {get;set;}
 public bool Rotate {get;set;}
 internal static readonly string[] Categories={"All designs","Valorant","Fortnite","Counter-Strike","All community games","Generated designs","Precision","Rings & targets","Creative","Saved presets"};
 internal void Validate(){if(!Categories.Contains(Category)||Duration<0||Duration>6||Delay<2||Delay>30)throw new ArgumentException("Invalid randomizer settings.");}
}
internal static class CrosshairGenerator {
 internal static CrosshairDesign Generate(Random random,CrosshairRandomOptions options,CrosshairDesign current,IEnumerable<CrosshairPreset> saved){
  options.Validate();var source=options.Category=="Saved presets"?saved:CrosshairCommunity.Games.Contains(options.Category)||options.Category=="All community games"?CrosshairCommunity.Pool(options.Category):options.Category=="All designs"?CrosshairStore.BuiltIn().Concat(CrosshairCommunity.Pool(options.Category)).Concat(saved):CrosshairStore.BuiltIn();var pool=source.Where(x=>options.Category switch{"Precision"=>new[]{"Cross","T shape","Dot","Chevron"}.Contains(x.Design.Shape),"Rings & targets"=>new[]{"Ring","Ring + cross","Double ring","Diamond","Square","Brackets"}.Contains(x.Design.Shape),"Creative"=>new[]{"Burst","Star","Triangle","Chevron"}.Contains(x.Design.Shape),_=>true}).ToArray();
  if(pool.Length==0)throw new ArgumentException("Save a design first, or choose another category.");var design=pool[random.Next(pool.Length)].Design.Copy();
  if(options.Category!="Saved presets"&&design.Shape!="Community"&&design.Shape!="Image"){design.Length=random.Next(3,options.Large?36:18);design.Thickness=random.Next(1,options.Large?7:4);design.Gap=random.Next(1,options.Large?16:9);design.Radius=random.Next(6,options.Large?38:20);design.DotSize=random.Next(1,options.Large?9:5);design.Dot=random.Next(2)==0;design.Outline=random.Next(3);design.Color=$"#{random.Next(80,256):X2}{random.Next(80,256):X2}{random.Next(80,256):X2}";design.Opacity=100;design.Rotation=options.Rotate?random.Next(0,24)*15:0;}
  if(options.LockColor)design.Color=current.Color;if(options.LockShape){design.Shape=current.Shape;design.ImageFile=current.ImageFile;design.ImageSize=current.ImageSize;design.CommunityId=current.CommunityId;design.PreparedDrawing=current.PreparedDrawing;design.PreparedImage=current.PreparedImage;}design.Validate();return design;
 }
}
